<style>
    .ventas-toolbar{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:20px}.ventas-table{width:100%;border-collapse:collapse}.ventas-table th,.ventas-table td{padding:13px 12px;border-bottom:1px solid #e5e7eb;text-align:left}.ventas-table th{font-size:.76rem;text-transform:uppercase;letter-spacing:.06em;color:#667085;background:#f8fafc}.ventas-table tr:last-child td{border-bottom:0}.ventas-actions{display:flex;gap:8px;flex-wrap:wrap}.ventas-button{display:inline-flex;align-items:center;justify-content:center;border:0;border-radius:9px;padding:9px 13px;font:inherit;font-weight:750;cursor:pointer;text-decoration:none}.ventas-button-primary{color:#fff;background:#2563eb}.ventas-button-light{color:#1f2937;background:#eef2f7}.ventas-button-danger{color:#991b1b;background:#fee2e2}.ventas-form{display:grid;grid-template-columns:1fr 1fr;gap:18px}.ventas-field-wide{grid-column:1/-1}.ventas-field label{display:block;font-weight:750;margin-bottom:6px}.ventas-field input,.ventas-field select{width:100%;min-height:44px;padding:9px 11px;border:1px solid #cbd5e1;border-radius:9px;background:#fff;font:inherit}.ventas-field small{display:block;margin-top:5px;color:#b42318}.ventas-form-actions{grid-column:1/-1;display:flex;justify-content:flex-end;gap:10px;margin-top:8px}.ventas-detail{display:grid;grid-template-columns:repeat(2,1fr);gap:14px}.ventas-detail div{padding:15px;border:1px solid #e5e7eb;border-radius:10px;background:#f8fafc}.ventas-detail dt{color:#667085;font-size:.78rem;font-weight:750;text-transform:uppercase}.ventas-detail dd{margin:5px 0 0;font-weight:700}.ventas-empty{text-align:center;padding:35px;color:#667085}.ventas-alert{padding:12px 14px;margin-bottom:18px;border-radius:9px;color:#166534;background:#dcfce7}@media(max-width:760px){.ventas-toolbar{align-items:stretch;flex-direction:column}.ventas-form,.ventas-detail{grid-template-columns:1fr}.ventas-field-wide,.ventas-form-actions{grid-column:auto}.ventas-table{display:block;overflow-x:auto}}
</style>
